mapper.select:
select brand.*
from goodscollection.brandcolllist
    inner join goodscollection.brand on brandcolllist.brandId = brand.brandId
where userId=#{userId}
order by id desc
limit 4 offset #{listLength}

select goodsId
from goodscollection.goodscolllist
where userId=#{userId}
order by id desc
limit 4 offset #{listLength}

select *
from goodscollection.goodscolllist
where userId=#{userId} and goodsId=#{goodsId}

select *
from goodscollection.brandcolllist
where userId=#{userId} and brandId=#{brandId}
